FUNCTION_BLOCK FB_P11
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorA : BOOL;
    SensorB : BOOL;
    SensorC : BOOL;
    ButtonA : BOOL;
    ButtonB : BOOL;
    ButtonC : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL := FALSE;
    MotorReverse : BOOL := FALSE;
    CompletionLight : BOOL := FALSE;
END_VAR
VAR
    (* 0: IDLE / A; 1: A->B; 2: B; 3: B->C; 4: C; 5: 完成 *)
    StationState : USINT := 0;
    StartupScans : USINT := 0;

    PreviousButtonA : BOOL := FALSE;
    PreviousButtonB : BOOL := FALSE;
    PreviousButtonC : BOOL := FALSE;
    RisingButtonA : BOOL;
    RisingButtonB : BOOL;
    RisingButtonC : BOOL;
END_VAR

(*
    每次调用为一个 20 ms 扫描周期。
    C10 的 [0,1] 按包含两个扫描周期实现；这比文字中的
    “上电首周期”更严格，启动期间不接受完成按钮事件。

    规约说明中的急停异常验证没有对应急停输入，属于待审信息；
    本接口不能实现或判定外部急停行为。
    本源码不代表已经通过编译或逐周期功能验证。
*)

RisingButtonA := ButtonA AND NOT PreviousButtonA;
RisingButtonB := ButtonB AND NOT PreviousButtonB;
RisingButtonC := ButtonC AND NOT PreviousButtonC;

PreviousButtonA := ButtonA;
PreviousButtonB := ButtonB;
PreviousButtonC := ButtonC;

(* 每周期先撤销电机命令，再按状态给出许可。 *)
MotorForward := FALSE;
MotorReverse := FALSE;

(* 完成灯的清除不受模式影响。 *)
IF NOT SensorC THEN
    CompletionLight := FALSE;
END_IF;

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;
    StationState := 0;
    CompletionLight := FALSE;

ELSIF NOT Mode THEN
    (* 手动退出自动序列；重新进入自动时从 A 开始。
       已点亮的完成灯仍保持到 SensorC 断开。 *)
    StationState := 0;
    MotorForward := ForwardButton AND NOT ReverseButton;
    MotorReverse := ReverseButton AND NOT ForwardButton;

ELSE
    IF CompletionLight THEN
        StationState := 5;
    END_IF;

    CASE StationState OF
        0:
            (* 当前站 A：到位且新完成事件才允许推进。 *)
            IF SensorA AND RisingButtonA THEN
                IF SensorB THEN
                    (* B 已到位，本扫描保持停止。 *)
                    StationState := 2;
                ELSE
                    StationState := 1;
                    MotorForward := TRUE;
                END_IF;
            END_IF;

        1:
            (* 转移途中无需持续按住 A 按钮或保持 SensorA。 *)
            IF SensorB THEN
                StationState := 2;
                (* 同扫描到位和完成事件有效，但到位扫描先停止。 *)
                IF RisingButtonB THEN
                    StationState := 3;
                END_IF;
            ELSE
                MotorForward := TRUE;
            END_IF;

        2:
            IF SensorB AND RisingButtonB THEN
                IF SensorC THEN
                    StationState := 4;
                ELSE
                    StationState := 3;
                    MotorForward := TRUE;
                END_IF;
            END_IF;

        3:
            IF SensorC THEN
                StationState := 4;
                IF RisingButtonC THEN
                    CompletionLight := TRUE;
                    StationState := 5;
                END_IF;
            ELSE
                MotorForward := TRUE;
            END_IF;

        4:
            IF SensorC AND RisingButtonC THEN
                CompletionLight := TRUE;
                StationState := 5;
            END_IF;

        5:
            (* 完成后保持停止，离开 C 后准备下一件产品。 *)
            IF NOT SensorC THEN
                StationState := 0;
            END_IF;

        ELSE
            (* 内部状态异常时停止并回到 A 等待。 *)
            StationState := 0;
    END_CASE;
END_IF;

END_FUNCTION_BLOCK
